@import url('https://fonts.googleapis.com/css2?family=DM+Sans:ital,opsz,wght@0,9..40,100..1000;1,9..40,100..1000&family=Inter:wght@300;400;500;600;700&display=swap');

:root {
  --green: #00824A;
  --green-light: #00A85F;
  --green-dark: #006B3D;
  --forest: #32462F;
  --cream: #F3CEA1;
  --cream-light: #FFF8EF;
  --cream-dark: #E8B87A;
  --brown: #4A3728;
  --brown-light: #6B5344;
  --white: #FFFFFF;
  --off-white: #FAFAF7;
  --gray-50: #F9FAFB;
  --gray-100: #F3F4F6;
  --gray-200: #E5E7EB;
  --gray-300: #D1D5DB;
  --gray-400: #9CA3AF;
  --gray-500: #6B7280;
  --gray-600: #4B5563;
  --gray-700: #374151;
  --gray-800: #1F2937;
  --gray-900: #111827;
  --text-primary: #1A1A1A;
  --text-secondary: #4B5563;
  --text-muted: #9CA3AF;
  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 16px;
  --radius-xl: 24px;
  --radius-full: 9999px;
  --shadow-sm: 0 1px 3px rgba(0,0,0,0.06), 0 1px 2px rgba(0,0,0,0.04);
  --shadow-md: 0 4px 12px rgba(0,0,0,0.08);
  --shadow-lg: 0 10px 30px rgba(0,0,0,0.1);
  --shadow-xl: 0 20px 50px rgba(0,0,0,0.12);
  --transition-fast: 150ms ease;
  --transition-base: 250ms ease;
  --transition-slow: 400ms ease;
  --max-width: 1280px;
  --header-height: 80px;
}

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html { scroll-behavior: smooth; -webkit-text-size-adjust: 100%; }

body {
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
  font-size: 16px;
  line-height: 1.6;
  color: var(--text-primary);
  background: var(--off-white);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

h1, h2, h3, h4, h5, h6 {
  font-family: 'DM Sans', sans-serif;
  font-weight: 700;
  line-height: 1.2;
  color: var(--forest);
}

h1 { font-size: clamp(2rem, 5vw, 3.5rem); }
h2 { font-size: clamp(1.5rem, 3.5vw, 2.5rem); }
h3 { font-size: clamp(1.25rem, 2.5vw, 1.75rem); }
h4 { font-size: 1.25rem; }

a { color: var(--green); text-decoration: none; transition: color var(--transition-fast); }
a:hover { color: var(--green-dark); }
a:focus-visible { outline: 2px solid var(--green); outline-offset: 2px; border-radius: 4px; }

img { max-width: 100%; height: auto; display: block; }

button {
  font-family: inherit;
  cursor: pointer;
  border: none;
  background: none;
  font-size: inherit;
  transition: all var(--transition-base);
}
button:focus-visible { outline: 2px solid var(--green); outline-offset: 2px; border-radius: 4px; }

.container { max-width: var(--max-width); margin: 0 auto; padding: 0 24px; }

@media (max-width: 768px) {
  .container { padding: 0 16px; }
}

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 12px 28px;
  border-radius: var(--radius-full);
  font-family: 'DM Sans', sans-serif;
  font-weight: 600;
  font-size: 0.938rem;
  line-height: 1.4;
  cursor: pointer;
  transition: all var(--transition-base);
  border: 2px solid transparent;
  text-align: center;
  min-height: 44px;
}

.btn-primary {
  background: var(--green);
  color: var(--white);
}
.btn-primary:hover { background: var(--green-dark); transform: translateY(-1px); box-shadow: var(--shadow-md); }
.btn-primary:active { transform: translateY(0); }

.btn-secondary {
  background: var(--white);
  color: var(--green);
  border-color: var(--green);
}
.btn-secondary:hover { background: var(--green); color: var(--white); }

.btn-dark {
  background: var(--forest);
  color: var(--white);
}
.btn-dark:hover { background: var(--brown); }

.btn-outline-white {
  background: transparent;
  color: var(--white);
  border-color: var(--white);
}
.btn-outline-white:hover { background: var(--white); color: var(--green); }

.btn-sm { padding: 8px 20px; font-size: 0.875rem; }
.btn-lg { padding: 16px 36px; font-size: 1.063rem; }

/* Header */
.site-header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: var(--white);
  box-shadow: 0 1px 0 rgba(0,0,0,0.06);
  height: var(--header-height);
}

.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 100%;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
}

.logo {
  display: flex;
  align-items: center;
  gap: 10px;
  text-decoration: none;
  flex-shrink: 0;
}

.logo-icon {
  width: 40px;
  height: 40px;
  background: var(--green);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
}

.logo-icon svg { width: 24px; height: 24px; }

.logo-text {
  font-family: 'DM Sans', sans-serif;
  font-weight: 700;
  font-size: 1.25rem;
  color: var(--forest);
}

.main-nav { display: flex; align-items: center; gap: 32px; }

.main-nav a {
  color: var(--text-primary);
  font-weight: 500;
  font-size: 0.938rem;
  padding: 8px 0;
  position: relative;
}
.main-nav a::after {
  content: '';
  position: absolute;
  bottom: 0;
  left: 0;
  width: 0;
  height: 2px;
  background: var(--green);
  transition: width var(--transition-base);
}
.main-nav a:hover { color: var(--green); }
.main-nav a:hover::after { width: 100%; }
.main-nav a.active { color: var(--green); }
.main-nav a.active::after { width: 100%; }

.header-actions { display: flex; align-items: center; gap: 16px; }

.header-actions a {
  font-weight: 500;
  font-size: 0.875rem;
  color: var(--text-secondary);
}

.mobile-menu-btn {
  display: none;
  width: 44px;
  height: 44px;
  align-items: center;
  justify-content: center;
  border-radius: var(--radius-sm);
}
.mobile-menu-btn svg { width: 24px; height: 24px; color: var(--text-primary); }

.mobile-nav {
  display: none;
  position: fixed;
  top: var(--header-height);
  left: 0;
  right: 0;
  bottom: 0;
  background: var(--white);
  z-index: 99;
  padding: 24px;
  flex-direction: column;
  gap: 8px;
  overflow-y: auto;
}

.mobile-nav.active { display: flex; }

.mobile-nav a {
  display: block;
  padding: 14px 16px;
  font-size: 1.063rem;
  font-weight: 500;
  color: var(--text-primary);
  border-radius: var(--radius-sm);
}
.mobile-nav a:hover { background: var(--gray-50); color: var(--green); }

.mobile-nav-actions {
  display: flex;
  gap: 12px;
  margin-top: 24px;
  padding-top: 24px;
  border-top: 1px solid var(--gray-200);
}

@media (max-width: 768px) {
  .main-nav { display: none; }
  .header-actions { display: none; }
  .mobile-menu-btn { display: flex; }
}

/* Footer */
.site-footer {
  background: var(--forest);
  color: var(--white);
  padding: 64px 0 32px;
  margin-top: 80px;
}

.footer-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 40px;
  margin-bottom: 48px;
}

.footer-col h4 {
  color: var(--cream);
  font-size: 0.938rem;
  font-weight: 600;
  margin-bottom: 16px;
  font-family: 'DM Sans', sans-serif;
}

.footer-col ul { list-style: none; }
.footer-col li { margin-bottom: 10px; }
.footer-col a {
  color: rgba(255,255,255,0.75);
  font-size: 0.875rem;
  transition: color var(--transition-fast);
}
.footer-col a:hover { color: var(--white); }

.footer-accordion-toggle {
  display: none;
  width: 100%;
  justify-content: space-between;
  align-items: center;
  padding: 16px 0;
  color: var(--cream);
  font-family: 'DM Sans', sans-serif;
  font-weight: 600;
  font-size: 0.938rem;
  border-bottom: 1px solid rgba(255,255,255,0.15);
  background: none;
  border-top: none;
  border-left: none;
  border-right: none;
  cursor: pointer;
}

.footer-accordion-toggle svg {
  width: 20px;
  height: 20px;
  transition: transform var(--transition-base);
  color: rgba(255,255,255,0.6);
}

.footer-accordion-toggle[aria-expanded="true"] svg { transform: rotate(180deg); }

.footer-bottom {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-top: 32px;
  border-top: 1px solid rgba(255,255,255,0.15);
  flex-wrap: wrap;
  gap: 16px;
}

.footer-social { display: flex; gap: 16px; }
.footer-social a {
  width: 40px;
  height: 40px;
  border-radius: 50%;
  background: rgba(255,255,255,0.1);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--white);
  transition: background var(--transition-fast);
}
.footer-social a:hover { background: rgba(255,255,255,0.2); }
.footer-social svg { width: 18px; height: 18px; }

.footer-legal {
  font-size: 0.813rem;
  color: rgba(255,255,255,0.5);
}

@media (max-width: 768px) {
  .site-footer { padding: 32px 0 24px; margin-top: 48px; }

  .footer-grid {
    grid-template-columns: 1fr;
    gap: 0;
  }

  .footer-col h4 { display: none; }

  .footer-accordion-toggle { display: flex; }

  .footer-col ul {
    max-height: 0;
    overflow: hidden;
    transition: max-height var(--transition-slow);
  }

  .footer-col.open ul { max-height: 400px; padding-bottom: 12px; }

  .footer-bottom { flex-direction: column; text-align: center; }
}

/* Cookie Banner */
.cookie-banner {
  position: fixed;
  bottom: 0;
  left: 0;
  right: 0;
  background: var(--white);
  box-shadow: 0 -4px 20px rgba(0,0,0,0.12);
  z-index: 200;
  padding: 20px 0;
  transition: transform var(--transition-slow);
}
.cookie-banner.hidden { transform: translateY(100%); pointer-events: none; }

.cookie-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  flex-wrap: wrap;
}

.cookie-text h4 {
  font-size: 1rem;
  color: var(--text-primary);
  margin-bottom: 4px;
}

.cookie-text p {
  font-size: 0.875rem;
  color: var(--text-secondary);
}

.cookie-actions { display: flex; gap: 12px; flex-shrink: 0; }

@media (max-width: 600px) {
  .cookie-inner { flex-direction: column; text-align: center; }
  .cookie-actions { width: 100%; justify-content: center; }
}

/* Section utilities */
.section { padding: 80px 0; }
.section-sm { padding: 48px 0; }
.section-lg { padding: 120px 0; }

.text-center { text-align: center; }
.text-green { color: var(--green); }
.text-cream { color: var(--cream); }
.text-white { color: var(--white); }

.bg-white { background: var(--white); }
.bg-cream { background: var(--cream-light); }
.bg-green { background: var(--green); }
.bg-forest { background: var(--forest); }

.badge {
  display: inline-flex;
  align-items: center;
  padding: 4px 14px;
  border-radius: var(--radius-full);
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.5px;
}
.badge-green { background: rgba(0,130,74,0.1); color: var(--green); }
.badge-cream { background: var(--cream); color: var(--brown); }

/* Card component */
.card {
  background: var(--white);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-sm);
  overflow: hidden;
  transition: all var(--transition-base);
}
.card:hover { box-shadow: var(--shadow-md); transform: translateY(-2px); }

.card-img {
  width: 100%;
  aspect-ratio: 16/10;
  background: var(--gray-100);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--gray-400);
  font-size: 0.875rem;
  overflow: hidden;
}

.card-body { padding: 20px; }
.card-body h3 { font-size: 1.125rem; margin-bottom: 8px; }
.card-body p { font-size: 0.875rem; color: var(--text-secondary); }

/* Grid layouts */
.grid-2 { display: grid; grid-template-columns: repeat(2, 1fr); gap: 32px; }
.grid-3 { display: grid; grid-template-columns: repeat(3, 1fr); gap: 32px; }
.grid-4 { display: grid; grid-template-columns: repeat(4, 1fr); gap: 24px; }

@media (max-width: 1024px) {
  .grid-4 { grid-template-columns: repeat(2, 1fr); }
  .grid-3 { grid-template-columns: repeat(2, 1fr); }
}
@media (max-width: 640px) {
  .grid-2, .grid-3, .grid-4 { grid-template-columns: 1fr; }
}

/* Promo blocks */
.promo-split {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 0;
  border-radius: var(--radius-lg);
  overflow: hidden;
  background: var(--white);
  box-shadow: var(--shadow-sm);
}
.promo-split .promo-img {
  aspect-ratio: 4/3;
  background: var(--gray-100);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--gray-400);
  font-size: 0.875rem;
}
.promo-split .promo-content {
  display: flex;
  flex-direction: column;
  justify-content: center;
  padding: 48px;
}
.promo-split .promo-content h2 { margin-bottom: 16px; }
.promo-split .promo-content p { color: var(--text-secondary); margin-bottom: 24px; line-height: 1.7; }

@media (max-width: 768px) {
  .promo-split { grid-template-columns: 1fr; }
  .promo-split .promo-content { padding: 32px 24px; }
}

/* Carousel */
.carousel-wrapper { position: relative; overflow: hidden; }

.carousel-track {
  display: flex;
  gap: 20px;
  transition: transform var(--transition-slow);
  will-change: transform;
}

.carousel-btn {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  width: 44px;
  height: 44px;
  border-radius: 50%;
  background: var(--white);
  box-shadow: var(--shadow-md);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 10;
  cursor: pointer;
  border: none;
  color: var(--text-primary);
  transition: all var(--transition-fast);
}
.carousel-btn:hover { box-shadow: var(--shadow-lg); background: var(--gray-50); }
.carousel-btn:disabled { opacity: 0.3; cursor: default; }
.carousel-btn svg { width: 20px; height: 20px; }

.carousel-prev { left: 8px; }
.carousel-next { right: 8px; }

/* Tabs */
.tabs { display: flex; gap: 4px; overflow-x: auto; -webkit-overflow-scrolling: touch; padding-bottom: 4px; }
.tabs::-webkit-scrollbar { display: none; }

.tab-btn {
  padding: 10px 24px;
  border-radius: var(--radius-full);
  font-weight: 600;
  font-size: 0.875rem;
  white-space: nowrap;
  background: var(--gray-100);
  color: var(--text-secondary);
  border: 2px solid transparent;
  min-height: 44px;
  cursor: pointer;
  transition: all var(--transition-fast);
}
.tab-btn:hover { background: var(--gray-200); color: var(--text-primary); }
.tab-btn.active { background: var(--green); color: var(--white); border-color: var(--green); }

.tab-panel { display: none; padding: 32px 0; }
.tab-panel.active { display: block; animation: fadeIn 250ms ease; }

@keyframes fadeIn { from { opacity: 0; transform: translateY(8px); } to { opacity: 1; transform: translateY(0); } }

/* Placeholder images */
.placeholder-img {
  background: linear-gradient(135deg, var(--gray-100) 0%, var(--gray-200) 100%);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--gray-400);
  font-size: 0.813rem;
  font-weight: 500;
  position: relative;
  overflow: hidden;
}

.placeholder-img::before {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(135deg, transparent 40%, rgba(255,255,255,0.4) 50%, transparent 60%);
}

.placeholder-coffee {
  background: linear-gradient(135deg, var(--cream-light) 0%, var(--cream) 100%);
  color: var(--brown-light);
}

.placeholder-green {
  background: linear-gradient(135deg, #E8F5E9 0%, #C8E6C9 100%);
  color: var(--green);
}

/* Skip link */
.skip-link {
  position: absolute;
  top: -100%;
  left: 16px;
  background: var(--green);
  color: var(--white);
  padding: 12px 24px;
  border-radius: var(--radius-sm);
  z-index: 999;
  font-weight: 600;
}
.skip-link:focus { top: 16px; }

/* Breadcrumb */
.breadcrumb {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 16px 0;
  font-size: 0.875rem;
  color: var(--text-muted);
}
.breadcrumb a { color: var(--text-secondary); }
.breadcrumb a:hover { color: var(--green); }
.breadcrumb span { color: var(--text-primary); font-weight: 500; }

/* Reduced motion */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    transition-duration: 0.01ms !important;
  }
  html { scroll-behavior: auto; }
}

