    function toggleMobileMenu() {
      const nav = document.getElementById('mobileNav');
      const btn = document.querySelector('.mobile-menu-btn');
      const isOpen = nav.classList.toggle('active');
      btn.setAttribute('aria-expanded', isOpen);
      document.body.style.overflow = isOpen ? 'hidden' : '';
    }
    function toggleFooterAccordion(btn) {
      const col = btn.parentElement;
      const wasOpen = col.classList.contains('open');
      document.querySelectorAll('.footer-col.open').forEach(c => { c.classList.remove('open'); c.querySelector('.footer-accordion-toggle')?.setAttribute('aria-expanded','false'); });
      if (!wasOpen) { col.classList.add('open'); btn.setAttribute('aria-expanded','true'); }
    }

    const carouselState = {};
    function slideCarousel(trackId, direction) {
      const track = document.getElementById(trackId);
      if (!track) return;
      const cards = track.children;
      const cardWidth = cards[0].offsetWidth + 20;
      const visible = Math.floor(track.parentElement.offsetWidth / cardWidth);
      const max = Math.max(0, cards.length - visible);
      if (!carouselState[trackId]) carouselState[trackId] = 0;
      carouselState[trackId] = Math.max(0, Math.min(max, carouselState[trackId] + direction));
      track.style.transform = `translateX(-${carouselState[trackId] * cardWidth}px)`;
    }

    function switchCategory(btn, panelId) {
      document.querySelectorAll('.category-tab').forEach(t => t.classList.remove('active'));
      document.querySelectorAll('.category-panel').forEach(p => p.classList.remove('active'));
      btn.classList.add('active');
      document.getElementById(panelId).classList.add('active');
    }

    function toggleFaq(btn) {
      const item = btn.parentElement;
      const wasOpen = item.classList.contains('open');
      document.querySelectorAll('.faq-item.open').forEach(i => {
        i.classList.remove('open');
        i.querySelector('.faq-toggle').setAttribute('aria-expanded', 'false');
      });
      if (!wasOpen) {
        item.classList.add('open');
        btn.setAttribute('aria-expanded', 'true');
      }
    }
  </script>
