  <script>
    function toggleMobileMenu() {
      const nav = document.getElementById('mobileNav');
      const btn = document.querySelector('.mobile-menu-btn');
      const isOpen = nav.classList.toggle('active');
      btn.setAttribute('aria-expanded', isOpen);
      document.body.style.overflow = isOpen ? 'hidden' : '';
    }

    function switchOrderType(btn) {
      document.querySelectorAll('.order-type-btn').forEach(b => b.classList.remove('active'));
      btn.classList.add('active');
    }

    function handleSearch(value) {
      const suggestions = document.getElementById('searchSuggestions');
      if (value.length >= 2) {
        suggestions.classList.add('visible');
      } else {
        suggestions.classList.remove('visible');
      }
    }

    function selectSuggestion(text) {
      document.getElementById('storeSearch').value = text;
      document.getElementById('searchSuggestions').classList.remove('visible');
    }

    document.addEventListener('click', function(e) {
      if (!e.target.closest('.search-input-wrap')) {
        document.getElementById('searchSuggestions').classList.remove('visible');
      }
    });

    function toggleFilters() {
      const panel = document.getElementById('filterPanel');
      const btn = document.getElementById('filterToggle');
      panel.classList.toggle('visible');
      btn.classList.toggle('active');
    }

    function selectStore(el) {
      document.querySelectorAll('.store-item.active').forEach(s => s.classList.remove('active'));
      el.classList.add('active');
    }
  </script>
